package webui

// Rows are de, nl, fr, es, zh-Hans. English is the exact compatibility label.
func newPresentationCatalog(rows map[string][5]string) map[string][6]string {
	result := make(map[string][6]string, len(rows))
	for english, translations := range rows {
		result[english] = [6]string{english, translations[0], translations[1], translations[2], translations[3], translations[4]}
	}
	return result
}

